// org.site.changeStandard — generated by `pnpm gen:command org change-standard`. Fill in the input, the change and the
// audit record. SOP rules go in ../rules (pnpm gen:rule), table access in ../repository.ts (02-architecture §3).
import { z } from 'zod';
import { defineCommand } from '../../kernel/index.ts';
import { orgPermissions } from '../permissions.ts';

export const changeStandard = defineCommand({
  name: 'org.site.changeStandard',
  permission: orgPermissions.changeStandard,
  input: z.object({ id: z.uuid() }),
  describe: (i) => `Change a site's standard L ↔ S (D-25) ${i.id}`,
  handle: (_ctx, i) =>
    Promise.resolve({
      result: { id: i.id },
      audit: { objectType: 'standard', objectId: i.id, clientId: null, before: null, after: null },
    }),
});
